  flaeche: "flaechen",
  projekt: "projekte",
  interesse: "interessen",
  provision: "provisionen",
  vorgaenge: "vorgaenge",
  flaechen: "flaechen",
  projekte: "projekte",
  interessen: "interessen",
  provisionen: "provisionen",
};

/** Bereich einer Admin-API aus dem Pfad (/api/admin/<teil>/…) */
const API_BEREICH = {
  uebersicht: "cockpit",
  vorgaenge: "vorgaenge",
  flaechen: "flaechen",
  projekte: "projekte",
  interessen: "interessen",
